import { Logger } from '@nestjs/common';
import { ERROR_LOGGER } from './health-check/error-logger/error-logger.provider.js';
import { JsonErrorLogger } from './health-check/error-logger/json-error-logger.service.js';
import { PrettyErrorLogger } from './health-check/error-logger/pretty-error-logger.service.js';
import { NOOP_LOGGER } from './health-check/logger/noop-logger.js';
import { TERMINUS_LOGGER, TERMINUS_MODULE_OPTIONS, } from './terminus.constants.js';
export const createOptionsProvider = (options = {}) => ({
    provide: TERMINUS_MODULE_OPTIONS,
    useValue: options,
});
export const createAsyncOptionsProvider = (options) => {
    if (options.useFactory) {
        return {
            provide: TERMINUS_MODULE_OPTIONS,
            useFactory: options.useFactory,
            inject: options.inject || [],
        };
    }
    return {
        provide: TERMINUS_MODULE_OPTIONS,
        useFactory: async (optionsFactory) => await optionsFactory.createTerminusOptions(),
        inject: [options.useExisting || options.useClass],
    };
};
export const createTerminusProviders = (options) => {
    return [
        {
            provide: ERROR_LOGGER,
            useFactory: (options) => {
                switch (options.errorLogStyle) {
                    case 'pretty':
                        return new PrettyErrorLogger();
                    default:
                        return new JsonErrorLogger();
                }
            },
            inject: [TERMINUS_MODULE_OPTIONS],
        },
        createLoggerProvider(options),
    ];
};
function createLoggerProvider(options) {
    // When options are known at registration time (forRoot / static @Module),
    // use static providers so NestJS resolves the logger through DI.
    if (options) {
        if (options.logger === false) {
            return { provide: TERMINUS_LOGGER, useValue: NOOP_LOGGER };
        }
        return {
            provide: TERMINUS_LOGGER,
            useClass: options.logger === true || options.logger === undefined
                ? Logger
                : options.logger,
        };
    }
    // When options are not known at registration time (forRootAsync),
    // the factory returns a resolved logger instance directly.
    return {
        provide: TERMINUS_LOGGER,
        useFactory: (opts) => {
            if (opts.logger === false) {
                return NOOP_LOGGER;
            }
            if (opts.logger === true || opts.logger === undefined) {
                return new Logger();
            }
            return opts.logger;
        },
        inject: [TERMINUS_MODULE_OPTIONS],
    };
}
